97	static int test_read_hw_feature(uintptr_t gmac_base)
98	{
99	  uint32_t feat0 = getreg32(gmac_base + GMAC_HW_FEATURE0);
100	
101	  ninfo("HW_FEATURE0 = 0x%08" PRIX32 "\n", feat0);
102	  ninfo("  MII(10/100M): %s\n", (feat0 & (1 << 0)) ? "YES" : "NO");
103	
104	  if (feat0 == 0x00000000 || feat0 == 0xFFFFFFFF)
105	    {
106	      nerr("ERROR: Invalid HW_FEATURE0 value, base address wrong?\n");
107	      return -1;
108	    }
109	
110	  return 0;
111	}
