113	/****************************************************************************
114	 * Private Functions - DMA Software Reset
115	 ****************************************************************************/
116	
117	static int dma_soft_reset(uintptr_t gmac_base)
118	{
119	  uint32_t val;
120	  int timeout = 100000;
121	
122	  val = getreg32(gmac_base + DMA_BUS_MODE);
123	  putreg32(val | DMA_SFT_RESET, gmac_base + DMA_BUS_MODE);
124	
125	  do
126	    {
127	      val = getreg32(gmac_base + DMA_BUS_MODE);
128	      if (!(val & DMA_SFT_RESET))
129	        {
130	          return 0;
131	        }
132	
133	      up_udelay(10);
134	    }
135	  while (--timeout > 0);
136	
137	  nerr("ERROR: DMA reset timeout\n");
138	  return -1;
139	}
