145	static void ephy_write_seq(uintptr_t base, const struct ephy_regval_s *seq,
146	                           unsigned int count)
147	{
148	  unsigned int i;
149	
150	  for (i = 0; i < count; i++)
151	    {
152	      putreg32(seq[i].value, base + seq[i].offset);
153	    }
154	}
