288	static void ephy_hardware_reset(uintptr_t phy_base, uintptr_t phy_top)
289	{
290	  uint32_t apb_id1;
291	  uint32_t apb_id2;
292	
293	  ephy_led_pinmux();
294	
295	  /* Select APB interface */
296	
297	  putreg32(0x0001, phy_top + 0x4);
298	
299	  /* Release shutdown */
300	
301	  putreg32(0x0900, phy_top);
302	
303	  /* Release dig_rst_n */
304	
305	  putreg32(0x0904, phy_top);
306	
307	  /* Switch to Page 5 */
308	
309	  putreg32(0x0500, phy_base + 0x7c);
310	
311	  /* ANA_PD */
312	
313	  putreg32(0x0c00, phy_base + 0x40);
314	
315	  /* ANA_EN */
316	
317	  putreg32(0x0c7e, phy_base + 0x40);
318	  up_mdelay(1);
319	
320	  /* Release ana_rst_n */
321	
322	  putreg32(0x0906, phy_top);
323	  putreg32(0x0500, phy_base + 0x7c);
324	
325	  /* Set PHY ID */
326	
327	  putreg32(0x0043, phy_base + 0x08);  /* PHY_ID_HIGH */
328	  putreg32(0x5649, phy_base + 0x0c);  /* PHY_ID_LOW */
329	
330	  ephy_full_analog_init(phy_base, phy_top);
331	
332	  putreg32(0x0001, phy_top + 0x4);
333	  putreg32(0x0500, phy_base + 0x7c);
334	  apb_id1 = getreg32(phy_base + 0x08) & 0xffff;
335	  apb_id2 = getreg32(phy_base + 0x0c) & 0xffff;
336	  syslog(LOG_INFO, "sg2000_eth: EPHY APB PHYID=0x%04" PRIX32
337	         "%04" PRIX32 "\n", apb_id1, apb_id2);
338	
339	  putreg32(0x0000, phy_base + 0x7c);
340	  putreg32(0x090e, phy_top);
341	  putreg32(getreg32(phy_base) | 0x0100, phy_base);
342	
343	  /* Switch back to MDIO control */
344	
345	  putreg32(0x0000, phy_top + 0x4);
346	  up_mdelay(10);
347	
348	  syslog(LOG_INFO, "sg2000_eth: EPHY init done top=0x%08" PRIX32
349	         " sel=0x%08" PRIX32 "\n",
350	         getreg32(phy_top), getreg32(phy_top + 0x4));
351	}
