353	static uint16_t mdio_read_status(uintptr_t gmac_base, int phy_addr, int reg,
354	                                 bool *timedout)
355	{
356	  uint32_t cmd;
357	  uint32_t val;
358	  int timeout = 10000;
359	
360	  if (timedout != NULL)
361	    {
362	      *timedout = false;
363	    }
364	
365	  do
366	    {
367	      if (!(getreg32(gmac_base + GMAC_MDIO_ADDR) & GMAC_MDIO_BUSY))
368	        {
369	          break;
370	        }
371	
372	      up_udelay(1);
373	    }
374	  while (--timeout > 0);
375	
376	  if (timeout <= 0)
377	    {
378	      if (timedout != NULL)
379	        {
380	          *timedout = true;
381	        }
382	
383	      return 0xffff;
384	    }
385	
386	  putreg32(0, gmac_base + GMAC_MDIO_DATA);
387	
388	  cmd = (((uint32_t)phy_addr << GMAC_MDIO_PA_SHIFT) & GMAC_MDIO_PA_MASK) |
389	        (((uint32_t)reg << GMAC_MDIO_RDA_SHIFT) & GMAC_MDIO_RDA_MASK) |
390	        GMAC_MDIO_CR_250_300M | GMAC_MDIO_GOC_READ | GMAC_MDIO_BUSY;
391	  putreg32(cmd, gmac_base + GMAC_MDIO_ADDR);
392	
393	  timeout = 10000;
394	  do
395	    {
396	      val = getreg32(gmac_base + GMAC_MDIO_ADDR);
397	      if (!(val & GMAC_MDIO_BUSY))
398	        {
399	          return getreg32(gmac_base + GMAC_MDIO_DATA) & 0xffff;
400	        }
401	
402	      up_udelay(1);
403	    }
404	  while (--timeout > 0);
405	
406	  if (timedout != NULL)
407	    {
408	      *timedout = true;
409	    }
410	
411	  return 0xffff;
412	}
