419	static void mdio_diag_scan(uintptr_t gmac_base)
420	{
421	  int phy;
422	
423	  for (phy = 0; phy < 32; phy++)
424	    {
425	      bool to1;
426	      bool to2;
427	      uint16_t id1 = mdio_read_status(gmac_base, phy, 2, &to1);
428	      uint16_t id2 = mdio_read_status(gmac_base, phy, 3, &to2);
429	      uint32_t id = ((uint32_t)id1 << 16) | id2;
430	
431	      syslog(LOG_INFO, "sg2000_eth: MDIO scan phy=%d id=0x%08" PRIX32
432	             " timeout=%d/%d\n", phy, id, to1 ? 1 : 0, to2 ? 1 : 0);
433	    }
434	}
435	
436	static void mdio_write(uintptr_t gmac_base, int phy_addr, int reg,
437	                       uint16_t data)
438	{
439	  uint32_t cmd;
440	  int timeout = 10000;
441	
442	  putreg32(data, gmac_base + GMAC_MDIO_DATA);
443	  cmd = (((uint32_t)phy_addr << GMAC_MDIO_PA_SHIFT) & GMAC_MDIO_PA_MASK) |
444	        (((uint32_t)reg << GMAC_MDIO_RDA_SHIFT) & GMAC_MDIO_RDA_MASK) |
445	        GMAC_MDIO_CR_250_300M | GMAC_MDIO_GOC_WRITE | GMAC_MDIO_BUSY;
446	  putreg32(cmd, gmac_base + GMAC_MDIO_ADDR);
447	
448	  do
449	    {
450	      if (!(getreg32(gmac_base + GMAC_MDIO_ADDR) & GMAC_MDIO_BUSY))
451	        {
452	          break;
453	        }
454	
455	      up_udelay(1);
456	    }
457	  while (--timeout > 0);
458	}
