460	/****************************************************************************
461	 * Private Functions - PHY Configuration
462	 ****************************************************************************/
463	
464	static int phy_config_init(struct sg2000_eth_priv_s *priv)
465	{
466	  uint16_t bmsr;
467	  uint16_t bmcr;
468	  uint16_t anlpar;
469	  int timeout;
470	
471	  /* Read PHY ID */
472	
473	  uint16_t id1 = mdio_read(priv->gmac_base, 0, 2);
474	  uint16_t id2 = mdio_read(priv->gmac_base, 0, 3);
475	  uint32_t phy_id = (id1 << 16) | id2;
476	
477	  syslog(LOG_INFO, "sg2000_eth: PHY ID=0x%08" PRIX32
478	         " expect=0x00435649\n", phy_id);
479	
480	  if (phy_id == 0xffffffff)
481	    {
482	      syslog(LOG_ERR, "sg2000_eth: PHY not responding\n");
483	      mdio_diag_scan(priv->gmac_base);
484	      return -1;
485	    }
486	
487	  if (phy_id != CVITEK_PHY_ID)
488	    {
489	      syslog(LOG_WARNING, "sg2000_eth: unexpected PHY ID 0x%08" PRIX32
490	             "\n", phy_id);
491	    }
492	
493	  priv->speed = 100;
494	  priv->duplex = 1;
495	
496	  /* Reset PHY */
497	
498	  mdio_write(priv->gmac_base, 0, 0, 0x8000);
499	  up_mdelay(10);
500	
501	  timeout = 100;
502	  do
503	    {
504	      bmcr = mdio_read(priv->gmac_base, 0, 0);
505	      if (!(bmcr & 0x8000))
506	        {
507	          break;
508	        }
509	
510	      up_mdelay(1);
511	    }
512	  while (--timeout > 0);
513	
514	  syslog(LOG_INFO, "sg2000_eth: PHY reset done, BMCR=0x%04X\n", bmcr);
515	
516	  /* Advertise 10/100 Full Duplex */
517	
518	  mdio_write(priv->gmac_base, 0, 4, 0x01e1);
519	
520	  /* Start auto-negotiation */
521	
522	  bmcr = mdio_read(priv->gmac_base, 0, 0);
523	  mdio_write(priv->gmac_base, 0, 0, bmcr | 0x1200);
524	  syslog(LOG_INFO, "sg2000_eth: autoneg start, BMCR=0x%04X\n",
525	         bmcr | 0x1200);
526	
527	  /* Wait for link.  BMSR link status is latch-low, so read it twice. */
528	
529	  timeout = 50;
530	  do
531	    {
532	      (void)mdio_read(priv->gmac_base, 0, 1);
533	      bmsr = mdio_read(priv->gmac_base, 0, 1);
534	      if ((bmsr & 0x0004) != 0)
535	        {
536	          break;
537	        }
538	
539	      up_mdelay(100);
540	    }
541	  while (--timeout > 0);
542	
543	  if ((bmsr & 0x0004) == 0)
544	    {
545	      syslog(LOG_WARNING, "sg2000_eth: PHY link down, BMSR=0x%04X\n",
546	             bmsr);
547	      priv->link_up = 0;
548	      return OK;
549	    }
550	
551	  anlpar = mdio_read(priv->gmac_base, 0, 5);
552	  syslog(LOG_INFO, "sg2000_eth: PHY link detected, BMSR=0x%04X "
553	         "ANLPAR=0x%04X\n", bmsr, anlpar);
554	
555	  if ((bmsr & 0x0020) == 0)
556	    {
557	      syslog(LOG_WARNING, "sg2000_eth: PHY autoneg incomplete, "
558	             "BMSR=0x%04X\n", bmsr);
559	    }
560	
561	  if ((anlpar & 0x0100) != 0)
562	    {
563	      priv->speed = 100;
564	      priv->duplex = 1;  /* Full */
565	    }
566	  else if ((anlpar & 0x0080) != 0)
567	    {
568	      priv->speed = 100;
569	      priv->duplex = 0;  /* Half */
570	    }
571	  else if ((anlpar & 0x0040) != 0)
572	    {
573	      priv->speed = 10;
574	      priv->duplex = 1;  /* Full */
575	    }
576	  else
577	    {
578	      priv->speed = 10;
579	      priv->duplex = 0;  /* Half */
580	    }
581	
582	  priv->link_up = 1;
583	  syslog(LOG_INFO, "sg2000_eth: PHY link up: %d Mbps %s duplex\n",
584	         priv->speed, priv->duplex ? "Full" : "Half");
585	  return 0;
586	}
