590	 ****************************************************************************/
591	
592	static int alloc_dma(struct sg2000_eth_priv_s *priv)
593	{
594	  int i;
595	
596	  priv->tx_desc = kmm_memalign(16, TX_RING_SIZE *
597	                                sizeof(struct sg2000_dma_desc_s));
598	  priv->rx_desc = kmm_memalign(16, RX_RING_SIZE *
599	                                sizeof(struct sg2000_dma_desc_s));
600	
601	  if (!priv->tx_desc || !priv->rx_desc)
602	    {
603	      return -ENOMEM;
604	    }
605	
606	  memset(priv->tx_desc, 0, TX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
607	  memset(priv->rx_desc, 0, RX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
608	
609	  /* For MMU-less or identity-mapped platforms, virtual address = physical.
610	   * TODO: For strict MMU kernel builds, use mm_virt_to_phys().
611	   */
612	
613	  priv->tx_desc_phys = (uint32_t)(uintptr_t)priv->tx_desc;
614	  priv->rx_desc_phys = (uint32_t)(uintptr_t)priv->rx_desc;
615	
616	  for (i = 0; i < TX_RING_SIZE; i++)
617	    {
618	      priv->tx_buf[i] = kmm_memalign(4, TX_BUF_SIZE);
619	      if (!priv->tx_buf[i])
620	        {
621	          return -ENOMEM;
622	        }
623	
624	      priv->tx_pkt[i] = NULL;
625	    }
626	
627	  for (i = 0; i < RX_RING_SIZE; i++)
628	    {
629	      priv->rx_buf[i] = kmm_memalign(4, RX_BUF_SIZE);
630	      if (!priv->rx_buf[i])
631	        {
632	          return -ENOMEM;
633	        }
634	    }
635	
636	  return 0;
637	}
638	
639	static void init_desc_and_dma(struct sg2000_eth_priv_s *priv)
640	{
641	  uintptr_t base = priv->gmac_base;
642	  uintptr_t dma = base + DMA_CHAN_BASE;
643	  int i;
644	
645	  /* Initialize TX descriptors */
646	
647	  for (i = 0; i < TX_RING_SIZE; i++)
648	    {
649	      priv->tx_desc[i].des0 = 0;
650	      priv->tx_desc[i].des2 = (uint32_t)(uintptr_t)priv->tx_buf[i];
651	      priv->tx_pkt[i] = NULL;
652	    }
653	
654	  /* Initialize RX descriptors: set OWN=1 (DMA owns them, can write) */
655	
656	  for (i = 0; i < RX_RING_SIZE; i++)
657	    {
658	      priv->rx_desc[i].des0 = DESC_OWN;
659	      priv->rx_desc[i].des1 = RX_BUF_SIZE;
660	      priv->rx_desc[i].des2 = (uint32_t)(uintptr_t)priv->rx_buf[i];
661	    }
662	
663	  priv->tx_cur = 0;
664	  priv->tx_dirty = 0;
665	  priv->rx_cur = 0;
666	
667	  /* Program DMA registers */
668	
669	  putreg32(DMA_SYS_DEFAULT, base + DMA_SYS_BUS_MODE);
670	  putreg32(TX_RING_SIZE - 1, dma + DMA_CHAN_TX_RING_LEN);
671	  putreg32(RX_RING_SIZE - 1, dma + DMA_CHAN_RX_RING_LEN);
672	  putreg32(priv->tx_desc_phys, dma + DMA_CHAN_TX_BASE_ADDR);
673	  putreg32(priv->rx_desc_phys, dma + DMA_CHAN_RX_BASE_ADDR);
674	  putreg32(DMA_INTR_DEFAULT_MASK, dma + DMA_CHAN_INTR_ENA);
675	}
676	
677	/****************************************************************************
678	 * Private Functions - MAC and DMA Control
679	 ****************************************************************************/
680	
681	static void set_mac_addr(uintptr_t gmac_base, const uint8_t *mac)
682	{
683	  uint32_t hi;
684	  uint32_t lo;
685	
686	  hi = (mac[5] << 8) | mac[4] | GMAC_HI_REG_AE;
687	  lo = (mac[3] << 24) | (mac[2] << 16) | (mac[1] << 8) | mac[0];
688	
689	  putreg32(hi, gmac_base + GMAC_ADDR_HIGH(0));
690	  putreg32(lo, gmac_base + GMAC_ADDR_LOW(0));
691	}
692	
693	static void start_mac_and_dma(struct sg2000_eth_priv_s *priv)
694	{
695	  uintptr_t gmac_base = priv->gmac_base;
696	  uintptr_t dma = gmac_base + DMA_CHAN_BASE;
697	  uint32_t v;
698	
699	  /* Configure MAC based on PHY negotiation results */
700	
701	  v = GMAC_CORE_INIT;
702	  if (priv->speed == 100)
703	    {
704	      v |= GMAC_CONFIG_FES;   /* 100M */
705	    }
706	
707	  if (priv->duplex)
708	    {
709	      v |= GMAC_CONFIG_DM;    /* Full duplex */
710	    }
711	
712	  putreg32(v, gmac_base + GMAC_CONFIG);
713	
714	  /* Packet filter: pass multicast + broadcast + unicast to us */
715	
716	  putreg32(GMAC_FILTER_HMC | GMAC_FILTER_PM | GMAC_FILTER_PR,
717	           gmac_base + GMAC_PACKET_FILTER);
718	
719	  /* Enable MAC interrupts */
720	
721	  putreg32(GMAC_INT_DEFAULT, gmac_base + GMAC_INT_EN);
722	
723	  /* Enable MAC TX and RX */
724	
725	  v = getreg32(gmac_base + GMAC_CONFIG);
726	  putreg32(v | GMAC_CONFIG_TE | GMAC_CONFIG_RE, gmac_base + GMAC_CONFIG);
727	
728	  /* Start TX DMA */
729	
730	  v = getreg32(dma + DMA_CHAN_TX_CONTROL);
731	  putreg32(v | DMA_TX_ST, dma + DMA_CHAN_TX_CONTROL);
732	
733	  /* Start RX DMA */
734	
735	  v = getreg32(dma + DMA_CHAN_RX_CONTROL);
736	  putreg32(v | DMA_RX_SR, dma + DMA_CHAN_RX_CONTROL);
737	}
738	
739	/****************************************************************************
740	 * Private Functions - Doorbell Helpers
741	 ****************************************************************************/
742	
743	static void tx_doorbell(struct sg2000_eth_priv_s *priv)
744	{
745	  uint32_t tail = priv->tx_desc_phys +
746	                  priv->tx_cur * sizeof(struct sg2000_dma_desc_s);
747	
748	  putreg32(tail, priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_END_ADDR);
749	}
750	
751	static void rx_doorbell(struct sg2000_eth_priv_s *priv)
752	{
753	  uint32_t tail = priv->rx_desc_phys +
754	                  priv->rx_cur * sizeof(struct sg2000_dma_desc_s);
755	
756	  putreg32(tail, priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_END_ADDR);
757	}
758	
759	/****************************************************************************
760	 * Private Functions - Hardware Transmit
761	 ****************************************************************************/
762	
763	static int hw_transmit(struct sg2000_eth_priv_s *priv,
764	                       const uint8_t *data, int len)
765	{
766	  unsigned int idx = priv->tx_cur;
767	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
768	  irqstate_t flags;
769	
770	  /* Check if the ring is full */
771	
772	  if (desc->des0 & DESC_OWN)
773	    {
774	      return -EBUSY;
775	    }
776	
777	  /* Copy data to DMA TX buffer */
778	
779	  memcpy(priv->tx_buf[idx], data, len);
780	
781	  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
782	  desc->des1 = len;
783	
784	  /* OWN | First Segment | Last Segment | Interrupt on Completion */
785	
786	  desc->des0 = DESC_OWN | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC |
787	               (len & RX_DESC_FL_MASK);
788	
789	  flags = up_irq_save();
790	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
791	
792	  /* Memory barrier: ensure descriptor is visible to DMA engine */
793	
794	  __asm__ volatile ("fence w,w" ::: "memory");
795	
796	  tx_doorbell(priv);
797	  up_irq_restore(flags);
798	
799	  return 0;
800	}
801	
802	/****************************************************************************
803	 * Private Functions - TX Cleanup (called from ISR on TX complete)
804	 ****************************************************************************/
805	
806	static void tx_cleanup(struct sg2000_eth_priv_s *priv)
807	{
808	  irqstate_t flags = up_irq_save();
809	
810	  while (priv->tx_dirty != priv->tx_cur)
811	    {
812	      struct sg2000_dma_desc_s *desc = &priv->tx_desc[priv->tx_dirty];
813	
814	      if (desc->des0 & DESC_OWN)
815	        {
816	          /* Still owned by DMA, stop */
817	
818	          break;
819	        }
820	
821	      /* Check for TX errors */
822	
823	      if (desc->des0 & TX_DESC_ES)
824	        {
825	          nerr("ERROR: TX error, status=0x%08" PRIX32 "\n", desc->des0);
826	        }
827	
828	      /* Free the netpkt if we have one tracked for this slot */
829	
830	      if (priv->tx_pkt[priv->tx_dirty] != NULL)
831	        {
832	          netpkt_free(&priv->dev, priv->tx_pkt[priv->tx_dirty], NETPKT_TX);
833	          priv->tx_pkt[priv->tx_dirty] = NULL;
834	
835	          /* Notify upper half that TX is done */
836	
837	          netdev_lower_txdone(&priv->dev);
838	        }
839	
840	      /* Move to next descriptor */
841	
842	      priv->tx_dirty = (priv->tx_dirty + 1) & (TX_RING_SIZE - 1);
843	    }
844	
845	  up_irq_restore(flags);
846	}
847	
848	/****************************************************************************
849	 * Private Functions - ISR
850	 ****************************************************************************/
851	
852	static int sg2000_eth_isr(int irq, void *context, void *arg)
853	{
854	  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
855	  uintptr_t base = priv->gmac_base;
856	  uintptr_t dma = base + DMA_CHAN_BASE;
857	  uint32_t status;
858	  uint32_t intr_en;
859	  uint32_t mac;
860	
861	  /* Clear MAC interrupts */
862	
863	  mac = getreg32(base + GMAC_INT_STATUS);
864	  if (mac)
865	    {
866	      putreg32(mac, base + GMAC_INT_STATUS);
867	    }
868	
869	  /* Read DMA channel status (only enabled interrupts) */
870	
871	  intr_en = getreg32(dma + DMA_CHAN_INTR_ENA);
872	  status = getreg32(dma + DMA_CHAN_STATUS) & intr_en;
873	
874	  if (!status)
875	    {
876	      return OK;
877	    }
878	
879	  /* Write-1-to-clear the status bits */
880	
881	  putreg32(status, dma + DMA_CHAN_STATUS);
882	
883	  if (status & DMA_STATUS_NIS)
884	    {
885	      /* Normal interrupt */
886	
887	      if (status & DMA_STATUS_RI)
888	        {
889	          /* RX complete: notify upper half that packets are ready.
890	           * The upper half will call our receive() callback to get them.
891	           */
892	
893	          netdev_lower_rxready(&priv->dev);
894	        }
895	
896	      if (status & DMA_STATUS_TI)
897	        {
898	          /* TX complete: cleanup descriptors and notify upper half */
899	
900	          tx_cleanup(priv);
901	        }
902	    }
903	
904	  if (status & DMA_STATUS_AIS)
905	    {
906	      /* Abnormal interrupt */
907	
908	      nerr("ERROR: DMA Abnormal: 0x%08" PRIX32 "\n", status);
909	
910	      if (status & DMA_STATUS_RBU)
911	        {
912	          nerr("ERROR: RX Buffer Unavailable\n");
913	        }
914	
915	      if (status & DMA_STATUS_TPS)
916	        {
917	          nerr("ERROR: TX Process Stopped\n");
918	        }
919	
920	      if (status & DMA_STATUS_FBE)
921	        {
922	          nerr("ERROR: Fatal Bus Error\n");
923	        }
924	    }
925	
926	  return OK;
927	}
928	
929	/****************************************************************************
930	 * Name: netdriver_ifup
931	 *
932	 * Description:
933	 *   OpenVela netdev_ops_s ifup callback.  Starts the network device.
934	 *
935	 ****************************************************************************/
936	
937	static int netdriver_ifup(FAR struct netdev_lowerhalf_s *dev)
938	{
939	  FAR struct sg2000_eth_priv_s *priv =
940	      (FAR struct sg2000_eth_priv_s *)dev;
941	  int ret;
942	
943	  syslog(LOG_INFO, "sg2000_eth: ifup begin\n");
944	
945	  ret = dma_soft_reset(priv->gmac_base);
946	  if (ret < 0)
947	    {
948	      nerr("ERROR: DMA reset failed before PHY init: %d\n", ret);
949	      return ret;
950	    }
951	
952	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
953	  up_mdelay(10);
954	
955	  syslog(LOG_INFO, "sg2000_eth: MDIO before PHY init addr=0x%08" PRIX32
956	         " data=0x%08" PRIX32 "\n",
957	         getreg32(priv->gmac_base + GMAC_MDIO_ADDR),
958	         getreg32(priv->gmac_base + GMAC_MDIO_DATA));
959	
960	  ret = phy_config_init(priv);
961	  if (ret < 0)
962	    {
963	      nerr("ERROR: PHY init failed: %d\n", ret);
964	      return ret;
965	    }
966	
967	  if (priv->tx_desc == NULL || priv->rx_desc == NULL)
968	    {
969	      ret = alloc_dma(priv);
970	      if (ret < 0)
971	        {
972	          nerr("ERROR: alloc_dma failed: %d\n", ret);
973	          return ret;
974	        }
975	    }
976	
977	  init_desc_and_dma(priv);
978	  set_mac_addr(priv->gmac_base, priv->mac_addr);
979	  start_mac_and_dma(priv);
980	  rx_doorbell(priv);
981	
982	  up_enable_irq(priv->irq);
983	  if (priv->link_up)
984	    {
985	      netdev_lower_carrier_on(dev);
986	    }
987	  else
988	    {
989	      netdev_lower_carrier_off(dev);
990	    }
991	
992	  syslog(LOG_INFO, "sg2000_eth: ifup done, %d Mbps %s duplex\n",
993	         priv->speed, priv->duplex ? "Full" : "Half");
994	
995	  return OK;
996	}
997	
998	/****************************************************************************
999	 * Name: netdriver_ifdown
1000	 *
1001	 * Description:
1002	 *   OpenVela netdev_ops_s ifdown callback.  Stops the network device.
1003	 *
1004	 ****************************************************************************/
1005	
1006	static int netdriver_ifdown(FAR struct netdev_lowerhalf_s *dev)
1007	{
1008	  FAR struct sg2000_eth_priv_s *priv =
1009	      (FAR struct sg2000_eth_priv_s *)dev;
1010	  uint32_t v;
1011	
1012	  up_disable_irq(priv->irq);
1013	
1014	  /* Stop TX DMA */
1015	
1016	  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);
1017	  putreg32(v & ~DMA_TX_ST,
1018	           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);
1019	
1020	  /* Stop RX DMA */
1021	
1022	  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
1023	  putreg32(v & ~DMA_RX_SR,
1024	           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
1025	
1026	  /* Disable MAC TX/RX */
1027	
1028	  v = getreg32(priv->gmac_base + GMAC_CONFIG);
1029	  putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE),
1030	           priv->gmac_base + GMAC_CONFIG);
1031	
1032	  netdev_lower_carrier_off(dev);
1033	
1034	  ninfo("netdriver_ifdown: interface down\n");
1035	
1036	  return OK;
1037	}
1038	
1039	/****************************************************************************
1040	 * Name: netdriver_transmit
1041	 *
1042	 * Description:
1043	 *   OpenVela netdev_ops_s transmit callback.  Sends a packet.
1044	 *   The driver takes ownership of the netpkt and MUST free it after TX
1045	 *   completion (or on error).
1046	 *
1047	 *   Returned Value:
1048	 *     OK on success (pkt queued for TX); negated errno on failure.
1049	 *
1050	 ****************************************************************************/
1051	
1052	static int netdriver_transmit(FAR struct netdev_lowerhalf_s *dev,
1053	                               FAR netpkt_t *pkt)
1054	{
1055	  FAR struct sg2000_eth_priv_s *priv =
1056	      (FAR struct sg2000_eth_priv_s *)dev;
1057	  unsigned int len = netpkt_getdatalen(dev, pkt);
1058	  uint8_t tmp_buf[SG2000_ETH_BUFSIZE];
1059	  const uint8_t *data;
1060	  int ret;
1061	
1062	  if (len > SG2000_ETH_BUFSIZE)
1063	    {
1064	      nerr("ERROR: TX packet too large: %u\n", len);
1065	      netpkt_free(dev, pkt, NETPKT_TX);
1066	      return -E2BIG;
1067	    }
1068	
1069	  /* Extract data from netpkt.  If fragmented, copy out; else use pointer. */
1070	
1071	  if (netpkt_is_fragmented(pkt))
1072	    {
1073	      netpkt_copyout(dev, tmp_buf, pkt, len, 0);
1074	      data = tmp_buf;
1075	    }
1076	  else
1077	    {
1078	      data = netpkt_getdata(dev, pkt);
1079	      if (!data)
1080	        {
1081	          nerr("ERROR: netpkt_getdata returned NULL\n");
1082	          netpkt_free(dev, pkt, NETPKT_TX);
1083	          return -EINVAL;
1084	        }
1085	    }
1086	
1087	  /* Send via DMA */
1088	
1089	  ret = hw_transmit(priv, data, len);
1090	  if (ret < 0)
1091	    {
1092	      nerr("ERROR: hw_transmit failed: %d\n", ret);
1093	      netpkt_free(dev, pkt, NETPKT_TX);
1094	      return ret;
1095	    }
1096	
1097	  /* Track this packet: store it so tx_cleanup can free it after DMA done.
1098	   * The tx_cur was already advanced by hw_transmit, so use (tx_cur - 1).
1099	   */
1100	
1101	  {
1102	    irqstate_t flags = up_irq_save();
1103	    unsigned int slot = (priv->tx_cur - 1) & (TX_RING_SIZE - 1);
1104	
1105	    priv->tx_pkt[slot] = pkt;
1106	    up_irq_restore(flags);
1107	  }
1108	
1109	  return OK;
1110	}
1111	
1112	/****************************************************************************
1113	 * Name: netdriver_receive
1114	 *
1115	 * Description:
1116	 *   OpenVela netdev_ops_s receive callback.  Called by upper half when
1117	 *   netdev_lower_rxready() was signaled.  Returns one received packet, or
1118	 *   NULL if no more packets are available.
1119	 *
1120	 *   Returned Value:
1121	 *     A netpkt_t * containing the received packet, or NULL.
1122	 *
1123	 ****************************************************************************/
1124	
1125	static FAR netpkt_t *netdriver_receive(FAR struct netdev_lowerhalf_s *dev)
1126	{
1127	  FAR struct sg2000_eth_priv_s *priv =
1128	      (FAR struct sg2000_eth_priv_s *)dev;
1129	  FAR netpkt_t *pkt = NULL;
1130	  struct sg2000_dma_desc_s *desc;
1131	  uint32_t status;
1132	  int frame_len;
1133	  int ret;
1134	
1135	  /* Check if there is a completed RX descriptor */
1136	
1137	  desc = &priv->rx_desc[priv->rx_cur];
1138	  if (desc->des0 & DESC_OWN)
1139	    {
1140	      /* DMA still owns it, no packet ready yet.
1141	       * This can happen if rxready was signaled for a previous packet
1142	       * that was already consumed, or in edge cases.
1143	       */
1144	
1145	      return NULL;
1146	    }
1147	
1148	  status = desc->des0;
1149	
1150	  /* Check for errors */
1151	
1152	  if (status & RX_DESC_ES)
1153	    {
1154	      nerr("ERROR: RX error, status=0x%08" PRIX32 "\n", status);
1155	      goto refill;
1156	    }
1157	
1158	  /* Get frame length (includes FCS which we strip) */
1159	
1160	  frame_len = ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK) - ETH_FCSSLEN;
1161	
1162	  if (frame_len <= 0 || frame_len > CONFIG_NET_ETH_PKTSIZE)
1163	    {
1164	      nwarn("WARNING: Invalid RX frame length: %d\n", frame_len);
1165	      goto refill;
1166	    }
1167	
1168	  /* Allocate a netpkt for the received data */
1169	
1170	  pkt = netpkt_alloc(dev, NETPKT_RX);
1171	  if (!pkt)
1172	    {
1173	      nerr("ERROR: netpkt_alloc failed\n");
1174	      goto refill;
1175	    }
1176	
1177	  /* Copy data from DMA RX buffer into the netpkt */
1178	
1179	  ret = netpkt_copyin(dev, pkt, priv->rx_buf[priv->rx_cur], frame_len, 0);
1180	  if (ret < 0)
1181	    {
1182	      nerr("ERROR: netpkt_copyin failed: %d\n", ret);
1183	      netpkt_free(dev, pkt, NETPKT_RX);
1184	      goto refill;
1185	    }
1186	
1187	  ninfo("RX packet: %d bytes\n", frame_len);
1188	
1189	refill:
1190	  /* Return the descriptor to DMA (set OWN=1) */
1191	
1192	  desc->des0 = DESC_OWN;
1193	  desc->des1 = RX_BUF_SIZE;
1194	
1195	  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
1196	  rx_doorbell(priv);
1197	
1198	  return pkt;
1199	}
