1201	/****************************************************************************
1202	 * Private Data - Operations Structure
1203	 *
1204	 * The netdev_ops_s maps our callbacks to the OpenVela lowerhalf API.
1205	 ****************************************************************************/
1206	
1207	static const struct netdev_ops_s g_ops =
1208	{
1209	  netdriver_ifup,     /* ifup */
1210	  netdriver_ifdown,   /* ifdown */
1211	  netdriver_transmit, /* transmit */
1212	  netdriver_receive   /* receive */
1213	  /* addmac, rmmac, ioctl, reclaim are not implemented for this simple
1214	   * Ethernet MAC driver.  They are only required for Wi-Fi or advanced
1215	   * filtering scenarios.
1216	   */
1217	};
1218	
1219	/****************************************************************************
1220	 * Public Functions
1221	 ****************************************************************************/
1222	
1223	/****************************************************************************
1224	 * Name: sg2000_eth_initialize
1225	 *
1226	 * Description:
1227	 *   Initialize the SG2000 Ethernet driver and register it with the OpenVela
1228	 *   network stack as a netdev_lowerhalf_s device.
1229	 *
1230	 *   Called from board_late_initialize() during system bringup.
1231	 *
1232	 ****************************************************************************/
1233	
1234	int sg2000_eth_initialize(void)
1235	{
1236	  FAR struct sg2000_eth_priv_s *priv = &g_eth_priv;
1237	  FAR struct netdev_lowerhalf_s *dev = &priv->dev;
