static void ephy_hardware_reset(uintptr_t phy_base, uintptr_t phy_top)
{
  uint32_t apb_id1;
  uint32_t apb_id2;

  ephy_led_pinmux();

  /* Minimal EPHY init sequence, matches Linux bm_eth_reset_phy() in
   * dwmac-cvitek.c and U-Boot cv181x_ephy_id_init() in board.c.
   * This ONLY releases resets and programs the PHY ID — it does NOT
   * run the full analog tuning sequence.  The full tuning (which
   * accesses internal pages and starts auto-negotiation) must run
   * AFTER the MDIO interface is confirmed operational, just as
   * Linux does in cv182xa_phy_config_init() -> config_init callback.
   */

  /* Select APB interface to access EPHY registers */

  putreg32(0x0001, phy_top + 0x4);

  /* Release shutdown */

  putreg32(0x0900, phy_top);

  /* Release dig_rst_n — enables MII register access via APB */

  putreg32(0x0904, phy_top);

  /* Switch to Page 5 for ANA init */

  putreg32(0x0500, phy_base + 0x7c);

  /* ANA_PD (power-down release) */

  putreg32(0x0c00, phy_base + 0x40);

  /* ANA_EN */

  putreg32(0x0c7e, phy_base + 0x40);
  up_mdelay(1);

  /* Release ana_rst_n */

  putreg32(0x0906, phy_top);
  putreg32(0x0500, phy_base + 0x7c);

  /* Program PHY ID into EPHY registers (so MDIO can discover it) */

  putreg32(0x0043, phy_base + 0x08);  /* PHY_ID_HIGH */
  putreg32(0x5649, phy_base + 0x0c);  /* PHY_ID_LOW */

  /* Read back PHY ID via APB for diagnostic verification */

  apb_id1 = getreg32(phy_base + 0x08) & 0xffff;
  apb_id2 = getreg32(phy_base + 0x0c) & 0xffff;
  syslog(LOG_INFO, "sg2000_eth: EPHY APB PHYID=0x%04" PRIX32
         "%04" PRIX32 "\n", apb_id1, apb_id2);

  /* Switch control to MDIO (GMAC) so the DWMAC4 MDIO controller can
   * discover and communicate with the PHY.
   */

  putreg32(0x0000, phy_top + 0x4);
  up_mdelay(10);

  syslog(LOG_INFO, "sg2000_eth: EPHY init done top=0x%08" PRIX32
         " sel=0x%08" PRIX32 "\n",
         getreg32(phy_top), getreg32(phy_top + 0x4));
}

/****************************************************************************
 * Name: ephy_full_tuning
 *
 * Description:
 *   Run the full CV182XA analog tuning sequence via APB, then switch back
 *   to MDIO control.  Matches Linux cv182xa_phy_config_init().
 *   MUST be called AFTER MDIO is confirmed operational, as it accesses
 *   internal pages and starts auto-negotiation which can interfere with
 *   MDIO if run before the MDIO interface is active.
 *
 ****************************************************************************/

static void ephy_full_tuning(uintptr_t phy_base, uintptr_t phy_top)
{
  /* ephy_full_analog_init expects APB mode; caller ensures MDIO is working
   * before we switch to APB for tuning.
   */

  putreg32(0x0001, phy_top + 0x4);
  ephy_full_analog_init(phy_base, phy_top);

  /* ephy_full_analog_init ends with:
   *   page 0 + autoneg start (0x090e) + force full-duplex
   * Switch control back to MDIO so the GMAC can manage the PHY.
   */

  putreg32(0x0000, phy_top + 0x4);
  up_mdelay(10);

  syslog(LOG_INFO, "sg2000_eth: EPHY full tuning done, top=0x%08" PRIX32
         " sel=0x%08" PRIX32 "\n",
         getreg32(phy_top), getreg32(phy_top + 0x4));
}

